$products?'':'disabled'?>>✓ Valider la vente</button></form><?php if($session):?><hr class="my-4"><details><summary class="fw-bold small" style="cursor:pointer">Opérations de caisse</summary><div class="pt-3"><h6>Dépense de caisse</h6><form method="post" action="<?=e(base_url('pos/expense'))?>" class="row g-2"><?=csrf_field()?><div class="col-5"><input class="form-control form-control-sm" type="number" step="0.01" min="0.01" name="amount" placeholder="FC" required></div><div class="col-7"><input class="form-control form-control-sm" name="description" placeholder="Motif" required></div><div class="col-12"><button class="btn btn-sm btn-soft w-100">Enregistrer dépense</button></div></form><hr><form method="post" action="<?=e(base_url('pos/close'))?>"><?=csrf_field()?><label class="form-label">Montant réel en caisse (FC)</label><div class="input-group"><input class="form-control" type="number" step="0.01" name="closing_amount" required><button class="btn btn-outline-danger" data-confirm="Clôturer la caisse ?">Clôturer</button></div></form></div></details><?php endif;?></div></aside></div>
